using System.Net.Http.Json;namespace PokeMarketApi.Services;public record CatalogCard(int Id,string Name,string CardNumber,string SetName,string Language,string Rarity,string? ImageUrl,decimal MarketPriceQar,string ProductType);public class CatalogClient(HttpClient http){public async Task<List<CatalogCard>> GetCards()=>await http.GetFromJsonAsync<List<CatalogCard>>("api/catalog/cards")??new();public async Task<CatalogCard?> GetCard(int id)=>await http.GetFromJsonAsync<CatalogCard>("api/catalog/cards/"+id);public async Task<List<string>> GetSets()=>await http.GetFromJsonAsync<List<string>>("api/catalog/sets")??new();}